import math

def score(program: str) -> float:
    n = len(program)
    if n == 0:
        return 0.0
    mean = sum(ord(c) for c in program) / n
    v = (mean - 60.0) / 40.0 * 0.8 + math.log(n + 1) / 50.0
    return max(0.0, min(1.0, v))

