    return max(0.0, min(1.0, a + b))

def score(program: str) -> float:
    try:
        s = "".join(program.split())
        n = len(s) + 1
        p = sum(not c.isalnum() for c in s) / n
        return min(1.0, max(0.0, 0.7 * n / (n + 1000.0) + 0.3 * p))
    except Exception:
        return 0.5

