import ast, zlib

def score(program: str) -> float:
    try:
        t = [type(n).__name__ for n in ast.walk(ast.parse(program))]
    except Exception:
        return 0.5
    return sum(zlib.crc32(s.encode()) % 1000 for s in t) / (999 * len(t))

